"""A tiny synthetic Dataset whose emissions are known: observations are generated by the plume forward model
from a chosen emission factor per day type, plus a constant background and a little noise."""

from dataclasses import dataclass, replace

import numpy as np

from nox_ml.data.inputs import Inputs
from nox_ml.inversion.linear import BACKGROUND_PIXEL, BACKGROUND_STATION, HOLIDAYS, hour_systems

TRUTH = {"weekday": 1.3, "saturday": 1.0, "sunday_holiday": 0.6}  # road factor of every region, by day type
TOLERANCE = 0.15  # relative error allowed on recovered emissions on the fixture
PLACEBO_TOLERANCE = 0.10  # |placebo center - 1| allowed on the fixture


@dataclass(frozen=True)
class Synthetic:
    data: Inputs
    truth_t_yr: dict[tuple[int, str], float]  # (zone, day type) -> road emission

    @property
    def sunday_ratio(self) -> float:
        return TRUTH["sunday_holiday"] / TRUTH["weekday"]


def synthetic_dataset(
    base: Inputs, seed: int = 1, noise_ppb: float = 0.5, strength: float = 20.0
) -> Synthetic:
    """`strength` scales the road prior so the stations respond enough to identify the factors."""
    rng = np.random.default_rng(seed)
    base = replace(base, zones=base.zones.assign(weight=base.zones["weight"] * strength))
    systems = hour_systems(base.hours, base.zones, base.points, base.no2_nox_ratio, base.n_regions, HOLIDAYS)
    factors = list(TRUTH.values())
    hours = []
    for hour, system in zip(base.hours, systems, strict=True):
        state = np.r_[base.points["prior"].to_numpy(), np.full(base.n_regions, factors[system.kind])]
        nox = (
            system.jacobian.stations @ state + BACKGROUND_STATION[0] + rng.normal(0, noise_ppb, len(hour.nox))
        )
        no2 = system.jacobian.pixels @ state + BACKGROUND_PIXEL[0] + rng.normal(0, 1e14, len(hour.no2))
        hours.append(replace(hour, nox=nox, no2=no2))
    prior = base.zones.groupby("region")["weight"].sum()
    truth = {(z, name): TRUTH[name] * prior[z] for z in range(base.n_regions) for name in TRUTH}
    return Synthetic(replace(base, hours=hours), truth)
